**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int cross(int px, int py, int qx, int qy, int rx, int ry) {
    return (qx - px) * (ry - py) - (qy - py) * (rx - px);
}

int main() {
    ifstream plik("odcinki.txt");
    int n;
    plik >> n;
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        int ax, ay, bx, by, cx, cy, dx, dy;
        plik >> ax >> ay >> bx >> by;
        plik >> cx >> cy >> dx >> dy;
        int d1 = cross(ax, ay, bx, by, cx, cy);
        int d2 = cross(ax, ay, bx, by, dx, dy);
        int d3 = cross(cx, cy, dx, dy, ax, ay);
        int d4 = cross(cx, cy, dx, dy, bx, by);
        bool intersect = false;
        if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
            ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
            intersect = true;
        }
        cout << "Para " << i + 1 << ": (" << ax << "," << ay << ")-(" << bx << "," << by
             << ") i (" << cx << "," << cy << ")-(" << dx << "," << dy << ") -> "
             << (intersect ? "PRZECINAJA SIE" : "NIE PRZECINAJA SIE") << endl;
        if (intersect) cnt++;
    }
    cout << "Przecinajace sie pary: " << cnt << endl;
    return 0;
}
```

**Wyjasnienie**: Odcinki AB i CD przecinaja sie, gdy C i D leza po roznych stronach prostej AB (rozne znaki cross(A,B,C) i cross(A,B,D)) ORAZ A i B leza po roznych stronach prostej CD. Pomijamy przypadki kolinearne (iloczyn = 0).

Weryfikacja:
- Para 1: AB=(0,0)-(4,4), CD=(0,4)-(4,0).
  d1=cross(0,0,4,4,0,4) = 4*4-4*0 = 16. d2=cross(0,0,4,4,4,0) = 4*0-4*4 = -16.
  d3=cross(0,4,4,0,0,0) = 4*(-4)-(-4)*0 = -16. d4=cross(0,4,4,0,4,4) = 4*0-(-4)*4 = 16.
  d1>0,d2<0 i d3<0,d4>0 -> PRZECINAJA SIE
- Para 2: AB=(0,0)-(2,0), CD=(3,0)-(5,0).
  d1=cross(0,0,2,0,3,0) = 2*0-0*3 = 0. d2=cross(0,0,2,0,5,0) = 2*0-0*5 = 0.
  d1=0, d2=0 (kolinearne) -> warunek d1*d2 rozne znaki nie spelniony -> NIE PRZECINAJA SIE
- Para 3: AB=(0,0)-(4,2), CD=(1,3)-(3,-1).
  d1=cross(0,0,4,2,1,3) = 4*3-2*1 = 10. d2=cross(0,0,4,2,3,-1) = 4*(-1)-2*3 = -10.
  d3=cross(1,3,3,-1,0,0) = 2*(-3)-(-4)*(-1) = -6-4 = -10. d4=cross(1,3,3,-1,4,2) = 2*(-1)-(-4)*3 = -2+12 = 10.
  Rozne znaki w obu parach -> PRZECINAJA SIE
- Para 4: AB=(0,0)-(1,1), CD=(2,2)-(3,3).
  d1=cross(0,0,1,1,2,2) = 1*2-1*2 = 0. d2=cross(0,0,1,1,3,3) = 1*3-1*3 = 0.
  Kolinearne -> NIE PRZECINAJA SIE
- Para 5: AB=(1,0)-(1,4), CD=(0,2)-(4,2).
  d1=cross(1,0,1,4,0,2) = 0*2-4*(-1) = 4. d2=cross(1,0,1,4,4,2) = 0*2-4*3 = -12.
  d3=cross(0,2,4,2,1,0) = 4*(-2)-0*1 = -8. d4=cross(0,2,4,2,1,4) = 4*2-0*1 = 8.
  Rozne znaki -> PRZECINAJA SIE
Przecinajace sie: 3.
